WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pc_ga_group_then_assign'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '分组后分配', 'kp-pc-ga-group-then-assign', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "分组后分配"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "先把元素打包分成几个组，再把这几个组分配给不同的人/部门。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“把 4 本不同的书分成两组，每组 2 本，分给甲乙两人，有几种分法？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导（极易错）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这题包含三个致命陷阱：分组、组内去重、全排列分配。"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分组：从 4 本里选 2 本作第一组 C(4,2) = 6，剩下的 2 本作第二组 C(2,2) = 1。组合数为 6。但这里存在【重复】！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "去重：如果第一组选了 AB，第二组自然是 CD。但这和第一组选 CD，第二组选 AB 是一模一样的分组结果！因为两组数量相等（都是2本），必须除以组数的全排列 A(2,2)。真实的纯分组方法只有 6 / 2 = 3 种！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分配：把这 3 种组好的包，分给甲乙两人，需要全排列 A(2,2) = 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "总计：3 × 2 = 6 种。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忘记除以等量组数的全排列：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "只要你把一堆东西分成了【数量相等】的若干组（不管组里面元素一样不一样），在单纯“分包”这一步，必须除以组数的全排列！分成 3 个数量相等的组，就除以 3!。"}]}]}]}$$ AS jsonb), NULL, '分组后分配的核心考点与实战推导。', category_node.id, CAST('["数量关系", "排列组合", "分组后分配"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pc_ga_group_then_assign", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
